// Native fixture is synthetic and generated by pob-item-popups-smoke.
const {_electron:electron}=require('playwright'),assert=require('node:assert/strict'),fs=require('node:fs'),path=require('node:path');
require('tsx/cjs');const {createDefaultState,createBuildDocument}=require('../src/shared/state.ts');
const fixture=JSON.parse(fs.readFileSync('.local/standalone-pob/item-popups-fixture.json','utf8')),root=path.resolve('.'),directory=path.join(root,'.local','item-popups-native-'+Date.now()),executable=process.env.POK_SMOKE_EXECUTABLE;
fs.mkdirSync(path.join(directory,'resources'),{recursive:true});for(const name of ['pob-runtime','pob-editor'])fs.symlinkSync(path.join(root,'resources',name),path.join(directory,'resources',name),'junction');
const a=createBuildDocument('Synthetic Popup Amulet',fixture.xml),u=createBuildDocument('Synthetic Popup Unique',fixture.uniqueXml),initial=createDefaultState();initial.builds=[a,u];initial.activeBuildId=a.id;initial.settings.pok.autoConnect=false;fs.mkdirSync(path.join(directory,'workspace'));fs.writeFileSync(path.join(directory,'workspace','workspace.v1.json'),JSON.stringify(initial));
const env={...process.env,POK_UI_DATA_DIR:directory,POK_UI_RESOURCE_DIR:path.join(directory,'resources')};delete env.ELECTRON_RUN_AS_NODE;delete env.POK_RENDERER_URL;
let app,page;const report={at:new Date().toISOString(),passed:[]};const current=()=>page.evaluate(async()=>{const s=await window.pok.loadState();return s.builds.find(b=>b.id===s.activeBuildId);});
async function poll(read,test){const end=Date.now()+120000;let value;do{value=await read();if(test(value))return value;await page.waitForTimeout(200);}while(Date.now()<end);throw new Error('Poll timed out: '+JSON.stringify(value));}
async function launch(){app=await electron.launch({executablePath:executable||path.join(root,'node_modules','electron','dist','electron.exe'),args:executable?[]:[root],cwd:directory,env,timeout:90000});page=await app.firstWindow();page.setDefaultTimeout(90000);await page.locator('.app-shell').waitFor();report.packaged=await app.evaluate(({app})=>app.isPackaged);if(executable)assert(report.packaged);}
async function openItem(){await page.getByRole('button',{name:'목걸이 슬롯',exact:true}).click();await poll(()=>page.getByRole('button',{name:'성유 1 편집',exact:true}).isEnabled(),Boolean);}
const dialog=()=>page.getByRole('dialog',{name:'아이템 옵션 선택',exact:true});
async function popupReady(){await poll(()=>dialog().getByRole('button',{name:/선택 완료/}).isEnabled(),Boolean);}
(async()=>{
  await launch();await openItem();await page.getByRole('button',{name:'성유 1 편집',exact:true}).click();await dialog().getByRole('button',{name:'팝업 취소',exact:true}).click();assert.equal(await dialog().count(),0);assert.equal((await current()).xml,a.xml);
  await page.getByRole('button',{name:'성유 1 편집',exact:true}).click();await popupReady();await dialog().getByLabel('성유 검색',{exact:true}).fill(fixture.node.name);await dialog().getByRole('button',{name:'목록 검색',exact:true}).click();await popupReady();await dialog().getByLabel('원본 성유 노드',{exact:true}).selectOption(String(fixture.node.id));await popupReady();assert.equal((await current()).revision,0);
  report.passed.push('a pending popup cancels without changing the build; original search and selection remain available afterwards');
  await page.getByRole('navigation',{name:'주요 메뉴'}).getByRole('button',{name:'노트',exact:true}).focus();await page.keyboard.press('Enter');await page.getByRole('navigation',{name:'주요 메뉴'}).getByRole('button',{name:'장비',exact:true}).click();await popupReady();assert.equal(await dialog().getByLabel('원본 성유 노드',{exact:true}).inputValue(),String(fixture.node.id));assert.equal((await current()).revision,0);report.passed.push('an unfinished original popup selection survives view navigation without changing XML');
  for(const [width,height] of [[1920,1080],[1024,768]]){await app.evaluate(({BrowserWindow},size)=>BrowserWindow.getAllWindows()[0].setContentSize(...size),[width,height]);assert(await page.evaluate(()=>document.documentElement.scrollWidth<=innerWidth+1));await page.screenshot({path:path.join(directory,'anoint-'+width+'.png')});}
  await dialog().getByRole('button',{name:/선택 완료/}).click();await poll(()=>dialog().count(),n=>n===0);let saved=await poll(current,b=>b.revision===1&&b.calculation?.revision===1);assert.equal(saved.calculation.result.stats.TotalDPS,fixture.anointedDps);assert.match(saved.xml,/<FutureItem value="keep"/);
  report.passed.push('native popup completion automatically creates a measured anointed revision and preserves unknown item XML');
  await poll(()=>page.getByRole('button',{name:'오염 편집',exact:true}).isEnabled(),Boolean);await page.getByRole('button',{name:'오염 편집',exact:true}).click();await popupReady();await dialog().getByRole('button',{name:/선택 완료/}).click();await poll(()=>dialog().count(),n=>n===0);saved=await poll(current,b=>b.revision===2&&b.calculation?.revision===2);assert(saved.xml.includes('Corrupted'));assert(saved.xml.includes('Allocates '+fixture.node.name));
  report.passed.push('native corruption preserves the anoint and reaches a separate measured revision');
  await page.getByLabel('현재 빌드',{exact:true}).selectOption(u.id);await openItem();await page.getByRole('button',{name:'오염 편집',exact:true}).click();await popupReady();await dialog().getByLabel('원본 오염 모드',{exact:true}).selectOption('rolls');await popupReady();const slider=dialog().getByLabel('팝업 '+fixture.slider,{exact:true});await slider.focus();await slider.press('End');await popupReady();await poll(()=>dialog().getByLabel('팝업 '+fixture.slider,{exact:true}).inputValue(),v=>Number(v)===1);
  for(const [width,height] of [[1920,1080],[1024,768]]){await app.evaluate(({BrowserWindow},size)=>BrowserWindow.getAllWindows()[0].setContentSize(...size),[width,height]);assert(await page.evaluate(()=>document.documentElement.scrollWidth<=innerWidth+1));await page.screenshot({path:path.join(directory,'corrupt-rolls-'+width+'.png')});}
  await dialog().getByRole('button',{name:/선택 완료/}).click();await page.getByLabel('현재 빌드',{exact:true}).selectOption(a.id);await poll(()=>page.evaluate(async id=>(await window.pok.loadState()).builds.find(b=>b.id===id),u.id),b=>b.revision===1);assert.equal((await current()).revision,2);await page.getByLabel('현재 빌드',{exact:true}).selectOption(u.id);const unique=await poll(current,b=>b.revision===1&&b.calculation?.revision===1);assert.equal(unique.calculation.result.stats.Dex,fixture.uniqueDex.after);assert.equal(unique.originalXml,u.originalXml);
  report.passed.push('original unique roll slider math reaches the same actual Dexterity as the native reference');
  await app.close();app=undefined;await launch();assert.equal((await current()).xml,unique.xml);assert.equal((await current()).calculation.revision,1);assert.equal((await page.evaluate(()=>window.pok.getPokConnection())).connected,false);
  report.passed.push('popup edits and measured revision survive restart; anoint/roll dialogs fit both desktop sizes without PoK');
})().catch(async error=>{report.error=error.stack;process.exitCode=1;if(page)await page.screenshot({path:path.join(directory,'failure.png')}).catch(()=>{});}).finally(async()=>{if(app)await app.close();fs.writeFileSync(path.join(directory,'result.json'),JSON.stringify(report,null,2));console.log(directory);if(report.error)console.error(report.error);});
